const input = $input.first().json;

const body =
  input.body && typeof input.body === 'object'
    ? input.body
    : input;

if (body.attachment) {
  return [{ json: { question: body.question, openaiModel: body.openaiModel, attachment: body.attachment } }];
}

const required = ['question', 'role', 'task'];

for (const field of required) {
  if (typeof body[field] !== 'string' || !body[field].trim()) {
    throw new Error(
      'UI Worker input error: ' +
      field +
      ' must be a non-empty string.'
    );
  }
}

if (
  !Number.isInteger(body.agentId) ||
  body.agentId < 1 ||
  body.agentId > 10
) {
  throw new Error(
    'UI Worker input error: agentId must be an integer from 1 to 10.'
  );
}

const agentCount = Number(body.agentCount ?? 1);

if (
  !Number.isInteger(agentCount) ||
  agentCount < 1 ||
  agentCount > 10
) {
  throw new Error(
    'UI Worker input error: agentCount must be an integer from 1 to 10.'
  );
}

return [
  {
    json: {
      question: body.question.trim(),
      replyLanguage: ['en', 'fr', 'tr'].includes(body.replyLanguage) ? body.replyLanguage : undefined,
      openaiModel:
        typeof body.openaiModel === 'string' && body.openaiModel.trim()
          ? body.openaiModel.trim()
          : 'gpt-5-mini',
      questionType:
        typeof body.questionType === 'string' && body.questionType.trim()
          ? body.questionType.trim()
          : 'genel',
      complexity:
        typeof body.complexity === 'string' && body.complexity.trim()
          ? body.complexity.trim()
          : 'low',
      agentCount,
      agentId: body.agentId,
      role: body.role.trim(),
      task: body.task.trim(),
    },
  },
];
